package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WebsiteUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property website url of user profile ")
  void test_website_url_v_o_builder() {
    Assertions.assertFalse(WebsiteUrlVO.nullValue().getWebsiteUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(WebsiteUrlVO.tryFrom(null).getWebsiteUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", WebsiteUrlVO.from("one").getWebsiteUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> WebsiteUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", WebsiteUrlVO.from("one").toString());
  }
}
